export function getAnswersByCompany(companyId: string): Answer[] {
  return ANSWERS.filter(a => a.companyId === companyId);
}

export function getAnswersByQuestion(questionId: string): Answer[] {
  return ANSWERS.filter(a => a.questionId === questionId);
}

export function getCompanyIds(): string[] {
  return [...new Set(ANSWERS.map(a => a.companyId))];
}
